        else{db()->prepare('INSERT INTO lead_forms(campaign_id,name,title,description,language,fields_json,style_json,success_message,public_token,is_active,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute([$campaignId,$name,$title,$description,$language,$json,$styleJson,$success,bin2hex(random_bytes(32)),$active,(int)$_SESSION['user_id']]);$id=(int)db()->lastInsertId();}
